-- Rathe definitions for a compatible published Field of Scale database.
-- Select the target explicitly. Use MariaDB 10.11 and stop on the first error.
SET @rathe_prior_sql_mode=@@SESSION.sql_mode;
SET SESSION sql_mode=CONCAT_WS(',',NULLIF(@@SESSION.sql_mode,''),'STRICT_ALL_TABLES','NO_ENGINE_SUBSTITUTION');
DELIMITER $$
BEGIN NOT ATOMIC
 DECLARE rathe_transaction_started BOOLEAN DEFAULT FALSE;
 DECLARE EXIT HANDLER FOR SQLEXCEPTION
 BEGIN
  IF rathe_transaction_started THEN ROLLBACK; END IF;
  SET SESSION sql_mode=@rathe_prior_sql_mode;
  RESIGNAL;
 END;
 IF DATABASE() IS NULL OR @@in_transaction<>0 THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Rathe exact serving identity/transaction differs';
 END IF;
 IF (SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_type='BASE TABLE' AND engine='InnoDB' AND table_name IN('tasks','dynamic_zone_templates','task_activities','tasksets','reward_sets','reward_options','rewards','reward_option_entries','reward_sources','npc_types','npc_faction','ground_spawns','rule_values','zone'))<>14 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Rathe14table InnoDB foundation differs'; END IF;
 START TRANSACTION;
 SET rathe_transaction_started=TRUE;
